        paragraphs: [
          'ನಿಮ್ಮ ಭಾಷಾ ಆದ್ಯತೆಯನ್ನು ನೆನಪಿಟ್ಟುಕೊಳ್ಳಲು ಮತ್ತು ನಿಮ್ಮನ್ನು ಸೈನ್-ಇನ್ ಆಗಿ ಇಡಲು ಅಗತ್ಯವಾದ ಬ್ರೌಸರ್ ಸಂಗ್ರಹಣೆಯನ್ನು ನಾವು ಬಳಸುತ್ತೇವೆ. ನಾವು ಪ್ರಸ್ತುತ ಮೂರನೇ ವ್ಯಕ್ತಿಯ ಜಾಹೀರಾತು ಅಥವಾ ಟ್ರ್ಯಾಕಿಂಗ್ ಕುಕೀಗಳನ್ನು ಬಳಸುವುದಿಲ್ಲ.',
        ],
