        'RDDBFI ಕಾಯಿದೆಯ ಶುಲ್ಕ ವೇಳಾಪಟ್ಟಿಯ ಅಡಿಯಲ್ಲಿ, ಹಕ್ಕು ಸಾಧಿಸಿದ ಮೊತ್ತದ ಆಧಾರದ ಮೇಲೆ ಲೆಕ್ಕಹಾಕಿದ ನಿಗದಿತ ಅರ್ಜಿ ಶುಲ್ಕವನ್ನು ಪಾವತಿಸಿ. ಪಾವತಿ ವಿಧಾನ — ಡಿಮ್ಯಾಂಡ್ ಡ್ರಾಫ್ಟ್, ಆನ್‌ಲೈನ್, ಅಥವಾ ಚಲನ್ — ಬೆಂಚ್‌ನಿಂದ ಬೆಂಚ್‌ಗೆ ಬದಲಾಗುತ್ತದೆ.',
        'ಒಬ್ಬ ವಕೀಲರು ನಿಮ್ಮ ಪರವಾಗಿ ಸಲ್ಲಿಸುತ್ತಿದ್ದರೆ ಒಂದು ವಕಾಲತ್‌ನಾಮಾವನ್ನು ಲಗತ್ತಿಸಿ, ಮತ್ತು ಅರ್ಜಿಯನ್ನು ದೃಢೀಕರಿಸುವ ಸರಿಯಾಗಿ ಪ್ರಮಾಣ ಮಾಡಿದ/ನೋಟರೀಕರಿಸಿದ ಪ್ರಮಾಣಪತ್ರವನ್ನು ಲಗತ್ತಿಸಿ.',
        'ಆಯ್ಕೆಮಾಡಿದ ಬೆಂಚ್‌ನ ರಿಜಿಸ್ಟ್ರಿ ಕೌಂಟರ್‌ನಲ್ಲಿ ಸಲ್ಲಿಸಿ, ಅಥವಾ ಆ ಬೆಂಚ್ ಇ-ಫೈಲಿಂಗ್ ಸೌಲಭ್ಯವನ್ನು ನೀಡಿದರೆ ಅದರ ಮೂಲಕ — ಪ್ರಸ್ತುತ ಲಭ್ಯತೆಯನ್ನು ರಿಜಿಸ್ಟ್ರಿಯೊಂದಿಗೆ ದೃಢೀಕರಿಸಿ.',
