        'ಕಡ್ಡಾಯ ಮುಂಗಡ ಠೇವಣಿಯನ್ನು ಪಾವತಿಸಿ. DRAT ಸಾಮಾನ್ಯವಾಗಿ DRT ನಿಗದಿಪಡಿಸಿದ ಬಾಕಿ ಮೊತ್ತದ 50% ಠೇವಣಿ ಇಲ್ಲದೆ ಯಾವುದೇ ಸಾಲಗಾರ/ಪ್ರತಿವಾದಿಯ ಮೇಲ್ಮನವಿಯನ್ನು ಸ್ವೀಕರಿಸುವುದಿಲ್ಲ — ಅರ್ಜಿಯ ಮೇಲೆ ಇದನ್ನು ಕನಿಷ್ಠ 25% ವರೆಗೆ ಕಡಿಮೆ ಮಾಡುವ ಸೀಮಿತ ವಿವೇಚನಾ ಅಧಿಕಾರವನ್ನು ನ್ಯಾಯಮಂಡಳಿ ಹೊಂದಿದೆ.',
